"use client";

import { useEffect, useState } from "react";
import type { Transition } from "motion/react";
import { useHydratedReducedMotion } from "@/lib/use-reduced-motion";
import { cn } from "@/lib/utils";

export { cn, useHydratedReducedMotion };

export type MomentProps = {
  className?: string;
  preview?: boolean;
};

export const springFast: Transition = { type: "spring", stiffness: 620, damping: 32 };
export const springSoft: Transition = { type: "spring", stiffness: 260, damping: 22 };
export const springBounce: Transition = { type: "spring", stiffness: 380, damping: 18 };
export const springHeavy: Transition = { type: "spring", stiffness: 200, damping: 26 };
export const springSnap: Transition = { type: "spring", stiffness: 700, damping: 38 };

export const tweenFast: Transition = { duration: 0.18, ease: [0.23, 1, 0.32, 1] };
export const tweenSoft: Transition = { duration: 0.32, ease: [0.23, 1, 0.32, 1] };

export const surface =
  "relative flex h-[150px] w-[230px] max-w-full select-none items-center justify-center text-foreground";

export function usePreviewPulse(
  preview: boolean | undefined,
  duration = 900,
  gap = 2500,
) {
  const [on, setOn] = useState(false);
  const reduce = useHydratedReducedMotion();

  useEffect(() => {
    if (!preview || reduce) {
      setOn(false);
      return;
    }
    let close = 0;
    let next = 0;
    const run = () => {
      setOn(true);
      close = window.setTimeout(() => setOn(false), duration);
      next = window.setTimeout(run, gap);
    };
    run();
    return () => {
      window.clearTimeout(close);
      window.clearTimeout(next);
    };
  }, [preview, reduce, duration, gap]);

  return on && !reduce;
}

export function usePreviewStep(
  preview: boolean | undefined,
  steps: number,
  interval = 1500,
) {
  const [step, setStep] = useState(0);
  const reduce = useHydratedReducedMotion();

  useEffect(() => {
    if (!preview || reduce) return;
    setStep(1);
    const id = window.setInterval(
      () => setStep((current) => (current + 1) % steps),
      interval,
    );
    return () => window.clearInterval(id);
  }, [preview, reduce, steps, interval]);

  return reduce ? 0 : step;
}

export function usePreviewPointer(
  preview: boolean | undefined,
  width = 220,
  height = 120,
) {
  const [point, setPoint] = useState({ x: width / 2, y: height / 2 });
  const reduce = useHydratedReducedMotion();

  useEffect(() => {
    if (!preview || reduce) return;
    let frame = 0;
    let start = 0;
    const loop = (time: number) => {
      if (!start) start = time;
      const t = (time - start) / 1000;
      const x = width / 2 + Math.cos(t * 1.4) * (width * 0.36);
      const y = height / 2 + Math.sin(t * 2.1) * (height * 0.28);
      setPoint({ x, y });
      frame = requestAnimationFrame(loop);
    };
    frame = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(frame);
  }, [preview, reduce, width, height]);

  return [point, setPoint] as const;
}

export function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

/**
 * The docs stage zooms its children (CSS `zoom`), so a pointer event reports
 * positions in zoomed pixels while the component lays itself out unscaled.
 * Normalise the event back into the component's own coordinate space.
 */
export function localPoint(
  event: { clientX: number; clientY: number },
  node: HTMLElement,
) {
  const rect = node.getBoundingClientRect();
  const scaleX = node.offsetWidth ? rect.width / node.offsetWidth : 1;
  const scaleY = node.offsetHeight ? rect.height / node.offsetHeight : 1;
  return {
    x: (event.clientX - rect.left) / (scaleX || 1),
    y: (event.clientY - rect.top) / (scaleY || 1),
  };
}

export function naturalWidth(node: HTMLElement) {
  return node.offsetWidth || node.getBoundingClientRect().width;
}

export function pointerScaleX(node: HTMLElement) {
  const rect = node.getBoundingClientRect();
  return node.offsetWidth ? rect.width / node.offsetWidth : 1;
}

"use client";

import { motion } from "motion/react";
import { useRef, useState } from "react";
import {
  clamp,
  cn,
  localPoint,
  naturalWidth,
  springBounce,
  surface,
  useHydratedReducedMotion,
  usePreviewPulse,
  type MomentProps,
} from "./shared";

const WIDTH = 206;
const HEIGHT = 84;
const MID = HEIGHT / 2;
const LEFT = 18;
const RIGHT = WIDTH - 18;
const CENTER = WIDTH / 2;
const LIMIT = 56;

function stringPath(pull: number, wobble = 0) {
  const bead = CENTER + pull;
  const bow = 2 + (Math.abs(pull) / LIMIT) * 12;
  const controlY = MID - bow + wobble;
  const leftControl = (LEFT + bead) / 2;
  const rightControl = (bead + RIGHT) / 2;
  return `M ${LEFT} ${MID} Q ${leftControl} ${controlY} ${bead} ${MID} Q ${rightControl} ${controlY} ${RIGHT} ${MID}`;
}

const VIBRATION = [0, 9, -6, 4, -2, 0];

export function ElasticString({ className, preview }: MomentProps) {
  const [pull, setPull] = useState(0);
  const [release, setRelease] = useState(0);
  const dragging = useRef(false);
  const band = useRef<HTMLDivElement>(null);
  const reduce = useHydratedReducedMotion();
  const pulse = usePreviewPulse(preview, 1100, 2600);
  const shown = preview ? (pulse ? 44 : 0) : pull;

  const setFromEvent = (event: React.PointerEvent) => {
    const node = band.current;
    if (!node) return;
    const point = localPoint(event, node);
    setPull(clamp(point.x - naturalWidth(node) / 2, -LIMIT, LIMIT));
  };

  const releaseString = () => {
    dragging.current = false;
    setPull(0);
    setRelease((value) => value + 1);
  };

  const key = (event: React.KeyboardEvent) => {
    if (event.key === "ArrowRight") {
      event.preventDefault();
      setPull((value) => clamp(value + 14, -LIMIT, LIMIT));
    }
    if (event.key === "ArrowLeft") {
      event.preventDefault();
      setPull((value) => clamp(value - 14, -LIMIT, LIMIT));
    }
    if (event.key === "Home") {
      event.preventDefault();
      setPull(-LIMIT);
    }
    if (event.key === "End") {
      event.preventDefault();
      setPull(LIMIT);
    }
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      releaseString();
    }
  };

  const restPath = stringPath(shown, 0);
  const pathAnimate =
    reduce || release === 0
      ? { d: restPath }
      : { d: VIBRATION.map((wobble) => stringPath(0, wobble)) };

  return (
    <div className={cn(surface, "flex-col gap-1", className)}>
      <div
        ref={band}
        role="slider"
        tabIndex={0}
        aria-label="Elastic string"
        aria-valuemin={-LIMIT}
        aria-valuemax={LIMIT}
        aria-valuenow={Math.round(shown)}
        aria-valuetext={`${Math.round(Math.abs(shown))} pixels ${
          shown < 0 ? "left" : "right"
        } of centre`}
        onKeyDown={key}
        onPointerDown={(event) => {
          dragging.current = true;
          event.currentTarget.setPointerCapture(event.pointerId);
          setFromEvent(event);
        }}
        onPointerMove={(event) => {
          if (dragging.current) setFromEvent(event);
        }}
        onPointerUp={releaseString}
        onPointerCancel={releaseString}
        className="relative h-[84px] w-[206px] touch-none rounded-xl outline-none focus-visible:ring-2 focus-visible:ring-white/50"
      >
        <svg
          aria-hidden="true"
          viewBox={`0 0 ${WIDTH} ${HEIGHT}`}
          className="absolute inset-0 size-full overflow-visible"
        >
          <path
            d={stringPath(0, 0)}
            fill="none"
            stroke="rgba(255,255,255,.08)"
            strokeWidth="10"
            strokeLinecap="round"
          />
          <motion.path
            key={`string-${release}`}
            fill="none"
            stroke="rgba(255,255,255,.62)"
            strokeWidth="2"
            strokeLinecap="round"
            initial={release === 0 ? false : { d: stringPath(0, 0) }}
            animate={pathAnimate}
            transition={
              reduce
                ? { duration: 0 }
                : release === 0
                  ? { duration: 0.12, ease: "easeOut" }
                  : { duration: 0.55, ease: [0.22, 1, 0.36, 1] }
            }
          />
          <circle cx={LEFT} cy={MID} r="4" fill="rgba(255,255,255,.75)" />
          <circle cx={RIGHT} cy={MID} r="4" fill="rgba(255,255,255,.75)" />
          <motion.circle
            aria-hidden="true"
            cx={CENTER}
            cy={MID}
            r="15"
            fill="rgba(255,255,255,.12)"
            initial={false}
            animate={{ cx: CENTER + shown }}
            transition={reduce ? { duration: 0 } : springBounce}
          />
          <motion.circle
            cx={CENTER}
            cy={MID}
            r="8"
            fill="#ffffff"
            stroke="rgba(255,255,255,.4)"
            strokeWidth="1"
            initial={false}
            animate={{ cx: CENTER + shown }}
            transition={reduce ? { duration: 0 } : springBounce}
          />
        </svg>
      </div>
      <span className="text-[10px] uppercase tracking-[0.2em] text-white/35">
        {Math.round(Math.abs(shown)) === 0 ? "Pull the bead" : `${Math.round(Math.abs(shown))} px`}
      </span>
    </div>
  );
}

"use client";

import { useReducedMotion } from "motion/react";
import { useSyncExternalStore } from "react";

const subscribe = () => () => {};

export function useHydratedReducedMotion() {
  const reduce = useReducedMotion() ?? false;
  const mounted = useSyncExternalStore(
    subscribe,
    () => true,
    () => false,
  );
  return mounted ? reduce : false;
}
